#!/bin/bash
# Profile one GEMM kernel with Instruments' "Performance Limiters" GPU counters.
# Generated by Claude (Opus 5.5); see README.md.
#
# usage: probes/profile_kernel.sh <file.metal> <function> <gridX> <gridY> <tgX> <tgY> [iters] [window]
#
# Records a Metal System Trace of run_kernel.swift, then prints the counters
# averaged over the kernel's GPU time (gpu_counters.py). The report is also
# saved to outputs/profiles/<function>.txt. The trace keeps only the last
# [window] of the run (default 4s), which must cover the warm-up and timed
# dispatches; counters are sampled every few microseconds, so a longer
# window makes the export much slower.
#
# xctrace has no public option for the counter set. The script copies Xcode's
# Metal System Trace template and sets its counter profile to 13, which on
# Apple M5 with Xcode 27 selects the "Performance Limiters" set (found by
# trying profiles 0-19; other GPUs or Xcode versions may number it
# differently, so check the report lists ALU and F32 counters).
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
root="$(dirname "$here")"
work="${TMPDIR:-/tmp}/metal-lab-profile"
mkdir -p "$work" "$root/outputs/profiles"

metal="$(cd "$(dirname "$1")" && pwd)/$(basename "$1")"
fn="$2"; shift 2
grid=("$1" "$2" "$3" "$4")
iters="${5:-3}"
window="${6:-4s}"

if [ ! -x "$work/run_kernel" ] || [ "$here/run_kernel.swift" -nt "$work/run_kernel" ]; then
  swiftc -O "$here/run_kernel.swift" -o "$work/run_kernel"
fi

template="$work/performance-limiters.tracetemplate"
if [ ! -f "$template" ]; then
  python3 - "$template" <<'EOF'
import plistlib, sys
src = ('/Applications/Xcode.app/Contents/Applications/Instruments.app/Contents/'
       'Packages/GPU.instrdst/Contents/Templates/Metal System Trace.tracetemplate')
doc = plistlib.load(open(src, 'rb'))
objs = doc['$objects']
for o in objs:
    if isinstance(o, dict) and 'NS.keys' in o:
        keys = [objs[k.data] for k in o['NS.keys']]
        if 'counterprofile' in keys:
            for k in ('counterprofile', 'counterprofileinternal'):
                objs.append(13)
                o['NS.objects'][keys.index(k)] = plistlib.UID(len(objs) - 1)
plistlib.dump(doc, open(sys.argv[1], 'wb'), fmt=plistlib.FMT_BINARY)
EOF
fi

trace="$work/$fn.trace"
rm -rf "$trace"
xcrun xctrace record --template "$template" --no-prompt --window "$window" --output "$trace" \
  --target-stdout - --launch -- "$work/run_kernel" "$metal" "$fn" "${grid[@]}" "$iters" \
  | tee "$work/$fn.stdout" | grep -v '^Starting\|^Ctrl-C\|^Target app\|^Recording\|^Output file\|^Launching'
{ grep " median " "$work/$fn.stdout"; python3 "$here/gpu_counters.py" "$trace" "$fn"; } \
  | tee "$root/outputs/profiles/$fn.txt"
